#ifndef MEMO_DAT_H
#define MEMO_DAT_H

/* memo.dat loader (compiler-spec.md sections 5 and 10), adapted from Wyvern Sorrow's dat.c.
 *
 * Differences from Wyvern: the header is not resident (an entry is one seek and one 8 byte
 * read), a whole scene's bytecode is read into dat_code[], strings stay on disk and are read
 * one at a time, and art is streamed in chunks.
 * Needs memo_ids.h (generated by memo_dat.py build) on the include path. */

#include <stdbool.h>
#include <stdint.h>

#include "memo_ids.h"

#define DAT_OK          0
#define DAT_ERR_OPEN    1   /* file missing */
#define DAT_ERR_IO      2   /* short read or seek failure */
#define DAT_ERR_MAGIC   3   /* not a memo.dat */
#define DAT_ERR_VERSION 4   /* format version differs from MEMO_FORMAT_VERSION */
#define DAT_ERR_CRC     5   /* built from different content than the engine's memo_ids.h */
#define DAT_ERR_BLOCK   6   /* block missing, unused, wrong type or malformed */
#define DAT_ERR_RANGE   7   /* scene number or size outside the limits */

#define DAT_TYPE_MAGIC       0
#define DAT_TYPE_TILESET     1
#define DAT_TYPE_PALETTE     2
#define DAT_TYPE_SCENE_CODE  3
#define DAT_TYPE_STRINGS     4
#define DAT_TYPE_TILEMAP     5
#define DAT_TYPE_TABLE       6
#define DAT_TYPE_MAPDEF      7
#define DAT_TYPE_PORTRAIT    8

/* INDEX tables, in file order (compiler-spec.md section 5.5). */
#define DAT_TABLE_MAPS       0   /* mapdef block */
#define DAT_TABLE_CGS        1   /* tiles, tilemap, palette */
#define DAT_TABLE_PORTRAITS  2   /* portrait block */
#define DAT_TABLE_SPRITES    3   /* tiles, palette */
#define DAT_TABLE_TILESETS   4   /* tiles, palette */
#define DAT_TABLE_MUSIC      5
#define DAT_TABLE_SFX        6
#define DAT_TABLE_COUNT      7

typedef struct {
    uint32_t offset;   /* file offset of the block data */
    uint16_t size;     /* block size in bytes */
    uint8_t  type;     /* DAT_TYPE_* */
    uint8_t  flags;    /* DAT_FLAG_* */
} DatEntry;

/* Scene bytecode: the whole current scene, valid after dat_load_scene(). */
extern uint8_t  dat_code[CODE_BUF_SIZE];
extern uint16_t dat_code_size;
extern uint16_t dat_code_entry;      /* program counter to start at */

extern uint8_t  dat_scene_count;
extern uint32_t dat_crc;             /* content CRC from META */

/* Open the file and check cookie and version. A non-zero expected_crc must equal the META
 * CRC (pass MEMO_CONTENT_CRC to be sure the file matches this build's memo_ids.h). */
uint8_t dat_open(const char *path, uint32_t expected_crc);
void    dat_close(void);

uint16_t dat_entry_count(void);
bool     dat_entry(uint16_t id, DatEntry *out);

/* Read n bytes at `offset` inside block `id`; fails if the range is outside the block. */
bool dat_read_block(uint16_t id, uint16_t offset, void *dst, uint16_t n);

/* VARS block: copies up to cap entries; *count receives the number in the file. */
bool dat_load_vars(uint8_t *vmax, uint8_t *vinit, uint8_t cap, uint8_t *count);

/* Read scene n (1-based) code into dat_code and prepare its string table. */
uint8_t dat_load_scene(uint8_t scene);

/* Read string `id` of the loaded scene into dst (cap bytes including the NUL). Returns the
 * bytes used including the NUL, or 0 if the id is bad or the string does not fit. */
uint8_t dat_load_string(uint16_t id, char *dst, uint8_t cap);

/* INDEX lookups: entry count of a table, and entry i (width u16 values into out). */
uint8_t dat_index_count(uint8_t table);
uint8_t dat_index_width(uint8_t table);
bool    dat_index_get(uint8_t table, uint8_t i, uint16_t *out);

/* Stream a whole block through buf (chunk bytes at a time) into sink. Missing art (size 0)
 * succeeds without calling the sink. */
typedef bool (*dat_sink_fn)(const uint8_t *data, uint16_t n, void *ctx);
bool dat_stream_block(uint16_t id, uint8_t *buf, uint16_t chunk, dat_sink_fn sink, void *ctx);

#endif /* MEMO_DAT_H */
